const projectId = 'REPLACE_WITH_ISOLATED_DNESKAI_PROJECT_UUID';
const origin = 'REPLACE_WITH_ISOLATED_OWN_PREVIEW_ORIGIN';
const workerId = 'REPLACE_WITH_THIS_PILOT_WORKFLOW_ID';
const expiresAt = '2026-10-15T09:10:00Z';
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const now = Date.now();
const expiry = Date.parse(expiresAt);
if (!uuid.test(projectId) || !/^[A-Za-z0-9]{8,64}$/.test(workerId) || workerId !== $workflow.id ||
    !/^https:\/\/own-dashboard-[a-z0-9]+-lukas-kourils-projects\.vercel\.app$/.test(origin)) {
  throw new Error('collection-pilot-configuration-required');
}
if (!Number.isFinite(now) || !Number.isFinite(expiry) || now + 60000 >= expiry) throw new Error('collection-pilot-expired');
const rows = $input.all();
const value = rows[0]?.json;
if (rows.length !== 1 || !value || typeof value !== 'object' || Array.isArray(value) ||
    Object.keys(value).some(key => !['projectId', 'runId', 'ticks', 'startedAt'].includes(key))) {
  throw new Error('collection-pilot-continuation-invalid');
}
const fresh = Object.keys(value).length === 0;
if (!fresh && (value.projectId !== projectId || !uuid.test(value.runId ?? '') ||
    !Number.isSafeInteger(value.ticks) || value.ticks < 1 || value.ticks >= 40 ||
    !Number.isSafeInteger(value.startedAt) || value.startedAt > now || value.startedAt < now - 40 * 120000)) {
  throw new Error('collection-pilot-continuation-invalid');
}
return [{json: {projectId, origin, workerId, expiresAt,
  runId: fresh ? null : value.runId, ticks: fresh ? 0 : value.ticks, startedAt: fresh ? now : value.startedAt}}];

const scope = $('Validate isolated scope').first().json;
const rows = $input.all();
const value = rows[0]?.json;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (rows.length !== 1 || !value || !uuid.test(value.runId ?? '') ||
    !['running','complete','partial','held','failed'].includes(value.status) || typeof value.continue !== 'boolean' ||
    (value.continue && value.status !== 'running') || (scope.runId !== null && value.runId !== scope.runId)) {
  throw new Error('collection-pilot-response-invalid');
}
const ticks = scope.ticks + 1;
const now = Date.now();
if (!Number.isSafeInteger(ticks) || ticks < 1 || ticks > 40 || !Number.isFinite(now)) throw new Error('collection-pilot-counter-invalid');
// Leave room for the fixed wait and one complete API request before the authorized expiry.
const expired = now + 75000 >= Date.parse(scope.expiresAt);
const exhausted = ticks >= 40;
const continuation = value.continue && !expired && !exhausted;
return [{json: {projectId: scope.projectId, runId: value.runId, ticks, startedAt: scope.startedAt,
  status: value.status, continue: continuation, approvalRequired: true,
  errorCode: value.continue ? (exhausted ? 'collection-pilot-tick-limit' : expired ? 'collection-pilot-expiry-near' : null) :
    value.status === 'running' ? 'collection-pilot-run-busy' : null}}];

const scope = $('Validate isolated scope').first().json;
const rows = $input.all();
const value = rows[0]?.json;
const now = Date.now();
if (rows.length !== 1 || !value || value.projectId !== scope.projectId || value.runId !== $('Bounded safe progress').first().json.runId ||
    value.continue !== true || value.status !== 'running' || !Number.isSafeInteger(value.ticks) || value.ticks < 1 || value.ticks >= 40 ||
    value.startedAt !== scope.startedAt || !Number.isFinite(now) || now + 60000 >= Date.parse(scope.expiresAt)) {
  throw new Error('collection-pilot-continuation-held');
}
// Native detached sub-workflow receives only this fixed control-state projection.
return [{json: {projectId: scope.projectId, runId: value.runId, ticks: value.ticks, startedAt: scope.startedAt}}];
